<template>
	<div>
		<div>
			<el-button type="success" icon="el-icon-check" size="medium" @click="save" v-loading.fullscreen.lock="fullscreenLoading">保存</el-button>
			<el-button type="danger" icon="el-icon-back" size="medium" @click="back">返回</el-button>

		</div>

		<el-row style="margin-top: 10px;" :gutter="20">
			<el-col :span='16'>
				<el-card shadow="never">
					<div slot="header" class="clearfix">
						<span>基础信息</span>
					</div>
					<el-form ref="form" :model="form" :inline="true" label-width="80px" :rules="rules">
						<el-form-item label="姓名:" prop="name">
							<el-input v-model="form.name" clearable></el-input>
						</el-form-item>
						<el-form-item label="电话:" prop="Account">
							<el-input v-model="form.Account" clearable></el-input>
						</el-form-item>
						<el-form-item label="住址:" prop="dizhi">
							<el-input v-model="form.dizhi" clearable></el-input>
						</el-form-item>
						 <el-form-item label="角色:">
							<el-autocomplete v-model="form.jiaose" :fetch-suggestions="querySearch" clearable style="width: 100%;"></el-autocomplete>
						</el-form-item> 

						<el-form-item v-if="passID!==''" label="密码:">
							<el-button @click="changePassword">修改密码</el-button>
						</el-form-item>
						<el-form-item v-else label="密码:" prop="Password">
							<el-input v-model="form.Password" clearable placeholder="请输入密码" show-password></el-input>
						</el-form-item>

						<!-- <el-form-item label="状态:">
							<el-checkbox v-model="form.Disable">停用账号</el-checkbox>
						</el-form-item> -->



					</el-form>
				</el-card>
			</el-col>


			<el-col :span='8'>
				<el-card shadow="never">
					<div slot="header" class="clearfix">
						<span>权限管理</span>
					</div>

					<div v-if="isDev" style="margin-bottom: 20px;">
						<el-button type="primary" size="mini" @click="refreshAuthTree">刷新</el-button>
	<!-- 					<el-button type="success" size="mini" @click="AddTreeNode(1)">新建同级</el-button>
						<el-button type="success" size="mini" @click="AddTreeNode(0)">新建下级</el-button>
						<el-button type="warning" size="mini" @click="RenameTreeNode">重命名</el-button>
						<el-button type="danger" size="mini" @click="DeleteTreeNode">删除</el-button> -->
					</div>

					<el-tree  :data="treedata" ref="AuthTree" node-key="id" :default-checked-keys="treecheck"
					 highlight-current show-checkbox :props="defaultProps" @node-click="handleNodeClick"></el-tree>
				</el-card>
			</el-col>
		</el-row>

	</div>
</template>

<script>
    import setter from '@/libs/setter.js'
	import {
	     //GetUserByID,
		//GetUserRoles,
		//UpdateUserPassword,
		UpdateUserByID,
		AddUser
	} from '@api/UserInfo.js'
	import {
		//GetAuthTree,
		AddAuth,
		UpdateAuthByID,
		DeleteAuth
	} from '@api/AuthInfo.js'
    import {
		Query,
		Aud
	} from '@api/shuju.js'
	import {
		GetMenuTreeOnAuth,
	} from '@api/sys.login.js'
	export default {
		data() {

			//密码输入框校检用的
			let checkPasswordPatter = /^[a-zA-Z]\w{5,17}$/;
			let checkPassword = (rule, value, callback) => {
				if (!checkPasswordPatter.test(value)) {
					return callback(new Error('以字母开头，长度在6~18之间，只能包含字母、数字和下划线'))
				} else {
					callback()
				}
			};


			return {
				fullscreenLoading: false,
				form: {
					name: '',
					Account: '',
					dizhi: '',
					jiaose:'',
					Disable: false,
					Status: 1,
				},
				roles: [],
				rules: {
					Name: [{
							required: true,
							message: '请输入姓名',
							trigger: 'blur'
						},
						{
							min: 2,
							max: 10,
							message: '长度在 2 到 10个字符',
							trigger: 'blur'
						}
					],
					Account: [{
							required: true,
							message: '请输入电话',
							trigger: 'blur'
						},
						{
							min: 3,
							max: 30,
							message: '账号在 3 到 30个字符',
							trigger: 'blur'
						}
					],
					Password: [{
						required: true,
						message: '请输入密码',
						trigger: 'blur'
					}, {
						validator: checkPassword
					}]
				},

				//目录树
				treedata: [],
				defaultProps: {
					children: 'children',
					label: 'label'
				},
				treecheck: [],
				isDev: false

			}
		},
		props: {
			//passID: String,
			passID: Number,
			authKeys: String
		},
		mounted() {
			this.checkDev()
			//this.InitRoles()
			this.InitUser()
			this.InitAuthFunTree()

		},
		methods: {
			back() {
				this.$emit('goBack')
			},
			checkDev() {
				this.isDev = (process.env.NODE_ENV === 'development') ? true : false
			},

			save() {
				this.$refs.form.validate((valid) => {
					if (valid) {
						this.fullscreenLoading = true;
						let arr2 = this.$refs.AuthTree.getCheckedKeys().filter(function(v,i){
                             if(typeof(v) != 'number'){
                                  return v
                                       }  
                                  });
                           console.log(JSON.stringify(arr2))
						if (this.passID !== '') { //有ID，就是保存更新
						console.log(this.passID)
						let xsz = setter.getTime().split(' ');
							Aud({
									/* Name: this.form.Name,
									Account: this.form.Account,
									Role: this.form.Role,
									ID: this.passID,
									Disable: this.form.Disable,
									Status: this.form.Status,
									AuthKeys: this.$refs.AuthTree.getCheckedKeys() */
									
							    reqType:'update',
					            content:[{
									用户名: this.form.name,
									联系方式: this.form.Account,
									住址: this.form.dizhi,
									角色:this.form.jiaose,
									'id': this.passID,
									功能权限:JSON.stringify(arr2),
									//time:xsz
								}],
					            tablename:'用户'
								})
								.then(res => {
									this.fullscreenLoading = false
									this.$message.success('保存成功')
									this.$emit('goBack')
								})
								.catch(err => {
									this.fullscreenLoading = false
								})
						} else { //无ID就是新建
						console.log(this.form.Name)
							Aud({
									//Name: this.form.Name,
									//Account: this.form.Account,
									//Role: this.form.Role,
									//Password: this.$md5(this.form.Password),
									//Password: this.form.Password,
									//Disable: this.form.Disable,
									//AuthKeys: this.$refs.AuthTree.getCheckedKeys().join(',')
								reqType:'append',
					            content:[{
									用户名: this.form.name,
									联系方式: this.form.Account,
									住址: this.form.dizhi,
									密码:this.form.Password,
									角色:this.form.jiaose,
									功能权限:JSON.stringify(arr2),
									//time:xsz
								}],
					            tablename:'用户'

								})
								.then(res => {
									this.fullscreenLoading = false
									this.$message.success('新建成功')
									this.$emit('goBack')
								})
								.catch(err => {
									this.fullscreenLoading = false
								})
						}
					} else {
						return false;
					}
				});

			},



			/* InitRoles() {
				Query({})
					.then(res => {
						this.roles = res.list
					})
					.catch(err => {})
			}, */

			//角色智能下拉---
			querySearch(queryString, cb) {
				let values = this.roles; //传入下拉列表数组
				let results = queryString ? values.filter(this.createFilter(queryString)) : values;
				// 调用 callback 返回建议列表的数据
				cb(results);
			},
			createFilter(queryString) {
				return (e) => {
					return (e.value.toLowerCase().indexOf(queryString.toLowerCase()) === 0);
				}
			},
			//角色智能下拉---


			InitUser() {
				if (this.passID !== '') { //有ID，说明是编辑，才去查询数据
					Query({
							tablename:'用户',
							field:'id',
							tj:`id= '${this.passID}'`
							//ID: this.passID
						})
						.then(res => {
							let xx = res.data
							//let xx = res
							this.form.name = xx[0].用户名
							this.form.Account =xx[0].联系方式
							this.form.dizhi = xx[0].住址
							this.form.jiaose = xx[0].角色
							//this.form.Status = res.Status
							this.treecheck = JSON.parse(xx[0].功能权限)
							
						}).catch(err => {})
				} else {
					//this.treecheck = [1, 2]
				}
			},

			changePassword() {
				this.$prompt('请输入新密码：', '提示', {
					confirmButtonText: '确定',
					cancelButtonText: '取消',
					inputPattern: /^[a-zA-Z]\w{5,17}$/,
					inputErrorMessage: '以字母开头，长度在6~18之间，只能包含字母、数字和下划线'
				}).then(({
					value
				}) => {
					Aud({
							//'id': this.passID,
							//密码: this.$md5(value)
							//密码: value
							reqType:'update',
					            content:[{
									//用户名: this.form.Name,
									//联系方式: this.form.Account,
									密码: value,
									id: this.passID,
								}],
					            tablename:'用户'
							
						})
						.then(res => {
							this.$message.success('密码修改成功')
						})
						.catch(err => {})
				}).catch(() => {});
			},



			InitAuthFunTree() {
				
			let sj =   JSON.parse(window.localStorage.getItem('d2admin-1.7.2'))
			let info = this.$store.state.d2admin.user.info
					        Query({
			                         tablename:'菜单',
			                          field:'id',
			                          tj:true  //加载条件										
									})
					 .then(res => {
					const tree = res.data;
					//const tree = res;
                       let str = '';
                        let tree1 = tree.filter(function(item,index){    //获取不重单
                        if(item.一级菜单 != str){
                         str = item.一级菜单;
                                    return item
			                        }
			                        })
									//console.log(menu1)
									 let tree2 = [];
                                tree1.forEach(function(item,index){     //对一级菜单进行遍历
                                  let obj2 = {
	                              label:item.一级菜单,
								  id:item.id
	                              //path:item.path,
	                              //icon: item.icon
		                           };
	                              let arr2 = [];
	                              tree.forEach(function(v,i){        //再对其所属的二级菜单进行遍历
	                            if(v.一级菜单 == item.一级菜单 ){
	                                   if(v.二级菜单 !=''){
	                                   arr2.push({
									   label:v.二级菜单,
									   id:v.二级菜单						
									   //path:v.path
	                                })
		                        }

		                    }
		                    })
		                    obj2.children = arr2;
	                        tree2.push(obj2)
                            })
							console.log(tree2)	
						this.treedata = tree2
					}).catch(err => {})
			},
			refreshAuthTree() {
				this.InitAuthFunTree()
				this.$message.success('刷新成功')
			},

			//控制台输出权限ID，方便我开发
			handleNodeClick(data) {
				//console.log(data.id)
				console.log(data.label + ":" + data.id)
			},
			getCheckedKeys() {
				let tl = this.$refs.AuthTree.getCheckedKeys()
				console.log(tl.join(","));
			},
			AddTreeNode(e) {
				let key = this.$refs.AuthTree.getCurrentKey()
				let s = (e === 1) ? ("同级") : ("下级")
				if (key !== null) {
					this.$prompt('请输入' + s + '节点名称', '提示', {
						confirmButtonText: '确定',
						cancelButtonText: '取消',
					}).then(({
						value
					}) => {
						AddAuth({
								Name: value,
								AuthKey: key,
								Same: e //传入1就是新建同级，传入0就是新建下级
							})
							.then(res => {
								if (e === 1) { //增加同级
									this.$refs.AuthTree.insertAfter(res.data, key)
								} else { //增加下级
									this.$refs.AuthTree.append(res.data, key)
								}
								this.$refs.AuthTree.setCurrentKey(res.data.AuthKey)
								this.$message.success('新建' + s + '节点成功')

							})
							.catch(err => {
								// 异常情况
							})

					}).catch(() => {});
				} else {
					this.$message({
						showClose: true,
						message: '请先选择节点',
						type: 'error'
					});
				}
			},
			RenameTreeNode() {
				let key = this.$refs.AuthTree.getCurrentKey()
				let data = this.$refs.AuthTree.getCurrentNode()
				if (key !== null) {
					this.$prompt('请输入节点新名称', '提示', {
						confirmButtonText: '确定',
						cancelButtonText: '取消',
						inputValue: data.label
					}).then(({
						value
					}) => {
						UpdateAuthByID({
								Name: value,
								AuthKey: key,
							})
							.then(res => {
								data.label = value
								this.$message.success('重命名成功')
							})
							.catch(err => {})

					}).catch(() => {});
				} else {
					this.$message.error('请先选择节点')
				}
			},


			DeleteTreeNode() {
				let key = this.$refs.AuthTree.getCurrentKey()
				if (key !== null) {
					let data = this.$refs.AuthTree.getCurrentNode()
					if (!data.children || data.children.length == 0) {
						this.$confirm('确定要删除该节点?', '提示', {
							confirmButtonText: '确定',
							cancelButtonText: '取消',
							type: 'warning'
						}).then(() => {
							DeleteAuth({
									AuthKey: key,
								})
								.then(res => {
									this.$refs.AuthTree.remove(key)
									this.$message.success('删除成功！')
								})
								.catch(err => {})
						}).catch(() => {});
					} else {
						this.$message.warning('该节点仍在子节点，不允许删除！');
					}
				} else {
					this.$message.warning('请先选择节点')
				}
			}
		},
	}
</script>

<style>
